styles.content:
/* Local Elastyc marketing header. Public brand colors are intentional. */
.wf-site-header{--es-ink:#102c3c;--es-mint:#42dbc1;--es-muted:#637781;position:sticky;top:0;z-index:1000;background:var(--wf-color-surface,#fff);color:var(--es-ink);border-bottom:1px solid #dce5e5;box-shadow:none;font-family:var(--wf-font-body,Arial,sans-serif)}
.wf-site-header *{box-sizing:border-box}
.wf-site-header__inner{width:min(1280px,calc(100% - 80px));min-height:84px;margin:0 auto;display:grid;grid-template-columns:160px minmax(0,1fr) auto;grid-template-areas:"brand navigation actions";align-items:center;gap:26px}
.wf-site-header [data-wf-component]{min-width:0}
.wf-site-header [data-wf-component="elastyc-site-brand"]{grid-area:brand}
.wf-site-header [data-wf-component="elastyc-site-navigation"]{grid-area:navigation}
.wf-site-header [data-wf-component="elastyc-site-actions"]{grid-area:actions}
.wf-site-header a:focus-visible,.wf-site-header button:focus-visible{outline:3px solid #168775;outline-offset:4px}
.wf-site-main{min-height:50vh}
.es-brand{display:inline-flex;align-items:center;min-height:44px;border-radius:4px;text-decoration:none}
.es-brand img{display:block;width:132px;height:38px;object-fit:contain}
.es-header-actions{display:flex;align-items:center;gap:22px}
.es-header-actions a{text-decoration:none;font-size:13px;font-weight:var(--wf-button-weight,600);white-space:nowrap}
.es-login{padding:12px 0;color:#546b78}
.es-login:hover{color:#147c69}
.es-contact{display:inline-flex;align-items:center;justify-content:center;gap:18px;min-height:44px;padding:12px 17px;border-radius:5px;background:#102c3c;color:white;transition:background .2s}
.es-contact:hover{background:#1c4858}
.es-contact svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.es-nav{height:84px;display:flex;align-items:center;justify-content:center}
.es-nav-panel{display:block}
.es-nav-list,.es-nav-children{padding:0;margin:0;list-style:none}
.es-nav-list{height:84px;display:flex;align-items:stretch;gap:4px}
.es-nav-list>.es-nav-item{display:flex;align-items:center;position:static}
.es-nav-link,.es-nav-group-button{font:inherit;text-decoration:none;font-size:14px;line-height:1.5;font-weight:var(--wf-menu-weight,500);color:#425d6b}
.es-nav-list>.es-nav-item>.es-nav-link,.es-nav-list>.es-nav-item>.es-nav-group-button{min-height:44px;display:flex;align-items:center;gap:8px;padding:11px 15px;border-radius:5px;white-space:nowrap}
.es-nav-group-button{border:0;background:none;cursor:pointer;text-align:left}
.es-nav-list>.es-nav-item>.es-nav-group-button:after{content:"";width:6px;height:6px;border-right:1.5px solid currentColor;border-bottom:1.5px solid currentColor;transform:translateY(-2px) rotate(45deg);transition:transform .18s}
.es-nav-list>.es-nav-item[data-es-open="true"]>.es-nav-group-button:after{transform:translateY(2px) rotate(225deg)}
.es-nav-list>.es-nav-item>.es-nav-link:hover,.es-nav-list>.es-nav-item>.es-nav-group-button:hover,.es-nav-list>.es-nav-item[data-es-open="true"]>.es-nav-group-button{background:#edf5f1;color:#156f5b}
.es-nav-list>.es-nav-item>.es-nav-children{display:none;position:absolute;left:50%;top:100%;transform:translateX(-50%);width:min(1080px,calc(100vw - 64px));padding:26px 30px 30px;border:1px solid #dce5df;border-top:3px solid #42dbc1;border-radius:0 0 9px 9px;background:#fff;box-shadow:0 24px 44px #061d2d20;max-height:calc(100dvh - 105px);overflow:auto;overscroll-behavior:contain;grid-template-columns:repeat(3,minmax(0,1fr));gap:25px 34px}
.es-nav-list>.es-nav-item[data-es-open="true"]>.es-nav-children{display:grid;animation:es-menu-in .15s ease-out}
.es-nav-list>.es-nav-item[data-wf-menu-key="solutions"]>.es-nav-children>.es-nav-item{border-top:1px solid #e4ece6;padding-top:15px}
.es-nav-list>.es-nav-item[data-wf-menu-key="solutions"]>.es-nav-children>.es-nav-item>.es-nav-link{font-size:14px;font-weight:var(--wf-menu-weight,500);color:#163a49;display:flex;align-items:center;justify-content:space-between;padding:0 8px 8px}
.es-nav-list>.es-nav-item[data-wf-menu-key="solutions"]>.es-nav-children>.es-nav-item>.es-nav-link:after{content:"↗";font-size:13px;color:#7c9b8d;font-weight:var(--wf-menu-weight,500)}
.es-nav-children .es-nav-children{display:block;position:static;margin:0;padding:0;border:0;box-shadow:none;background:none;transform:none;width:auto}
.es-nav-children .es-nav-link{display:block;padding:9px 9px;color:#637b83;border-radius:4px;font-size:12px;font-weight:var(--wf-menu-weight,500);white-space:normal}
.es-nav-children .es-nav-link:hover{background:#f0f6f0;color:#176e58}
.es-nav-children [data-wf-menu-presentation="featured"]>.es-nav-link{background:#e1f4e9;color:#1c6a50;font-weight:var(--wf-menu-weight,500)}
.es-nav-list>.es-nav-item[data-wf-menu-key="platform"]>.es-nav-children{width:min(670px,calc(100vw - 64px));grid-template-columns:1fr 1fr;gap:3px 24px;padding:23px}
.es-nav-list>.es-nav-item[data-wf-menu-key="resources"]>.es-nav-children{width:min(420px,calc(100vw - 64px));grid-template-columns:1fr;gap:4px;padding:21px}
.es-nav-list>.es-nav-item[data-wf-menu-key="platform"]>.es-nav-children>.es-nav-item>.es-nav-link,.es-nav-list>.es-nav-item[data-wf-menu-key="resources"]>.es-nav-children>.es-nav-item>.es-nav-link{font-size:13px;padding:12px 14px;font-weight:var(--wf-menu-weight,500)}
.es-nav-toggle,.es-nav-mobile-actions{display:none}
@keyframes es-menu-in{from{opacity:0;translate:0 -5px}to{opacity:1;translate:0 0}}
@media(max-width:1150px){.wf-site-header__inner{width:calc(100% - 48px);grid-template-columns:135px minmax(0,1fr) auto;gap:14px}.es-nav-list>.es-nav-item>.es-nav-link,.es-nav-list>.es-nav-item>.es-nav-group-button{padding-inline:11px;font-size:13px}.es-header-actions{gap:15px}.es-header-actions a{font-size:12px}.es-contact{padding-inline:14px;gap:12px}}
@media(max-width:980px){
 .wf-site-header__inner{min-height:74px;width:calc(100% - 40px);grid-template-columns:minmax(0,1fr) auto;grid-template-areas:"brand navigation";gap:20px}
 .wf-site-header [data-wf-component="elastyc-site-actions"]{display:none}
 .es-brand img{width:119px;height:34px}.es-nav{height:74px;justify-content:flex-end}
 .es-nav-toggle{display:flex;align-items:center;gap:11px;height:44px;padding:10px 12px;border:1px solid #d6e2df;background:#fff;color:#274955;border-radius:5px;font:inherit;font-size:12px;font-weight:var(--wf-menu-weight,500);cursor:pointer}
 .es-nav-toggle-icon{display:flex;flex-direction:column;gap:4px;width:18px}.es-nav-toggle-icon i{display:block;height:1.5px;background:currentColor;width:18px;transition:transform .2s,opacity .2s}
 .wf-site-header[data-wf-menu-open="true"] .es-nav-toggle-icon i:nth-child(1){transform:translateY(5.5px) rotate(45deg)}.wf-site-header[data-wf-menu-open="true"] .es-nav-toggle-icon i:nth-child(2){opacity:0}.wf-site-header[data-wf-menu-open="true"] .es-nav-toggle-icon i:nth-child(3){transform:translateY(-5.5px) rotate(-45deg)}
 .es-nav-panel{display:none;position:absolute;left:0;right:0;top:100%;max-height:calc(100dvh - 74px);overflow-y:auto;overscroll-behavior:contain;background:#fff;border-top:1px solid #e2eae4;border-bottom:1px solid #d6e2da;box-shadow:0 22px 30px #061d2d18;padding:12px 20px 0}
 .wf-site-header[data-wf-menu-open="true"] .es-nav-panel{display:block}
 .es-nav-list{height:auto;display:block}.es-nav-list>.es-nav-item{display:block;border-bottom:1px solid #e6ede6}
 .es-nav-list>.es-nav-item>.es-nav-link,.es-nav-list>.es-nav-item>.es-nav-group-button{width:100%;min-height:53px;padding:15px 8px;justify-content:space-between;font-size:15px;border-radius:0}
 .es-nav-list>.es-nav-item>.es-nav-children,.es-nav-list>.es-nav-item[data-wf-menu-key="platform"]>.es-nav-children,.es-nav-list>.es-nav-item[data-wf-menu-key="resources"]>.es-nav-children{position:static;left:auto;top:auto;transform:none;width:100%;padding:4px 8px 19px;border:0;border-radius:0;box-shadow:none;max-height:none;overflow:visible;grid-template-columns:1fr;gap:18px;animation:none}
 .es-nav-list>.es-nav-item[data-wf-menu-key="solutions"]>.es-nav-children>.es-nav-item{padding-top:13px}.es-nav-list>.es-nav-item[data-wf-menu-key="solutions"]>.es-nav-children>.es-nav-item>.es-nav-link{padding:4px 9px 9px;font-size:14px}
 .es-nav-children .es-nav-link{padding:11px 12px;font-size:13px}.es-nav-list>.es-nav-item[data-wf-menu-key="platform"]>.es-nav-children,.es-nav-list>.es-nav-item[data-wf-menu-key="resources"]>.es-nav-children{gap:3px}
 .es-nav-mobile-actions{display:flex;gap:20px;align-items:center;justify-content:space-between;position:sticky;bottom:0;background:#fff;border-top:1px solid #e4ece5;padding:17px 2px;z-index:2}
 .es-nav-mobile-actions>a{font-size:12px;font-weight:var(--wf-menu-weight,500);color:#546f78;text-decoration:none;min-height:44px;display:flex;align-items:center}.es-nav-mobile-actions>a.es-nav-mobile-cta{background:#102c3c;color:#fff;border-radius:5px;padding:12px 17px;gap:20px}
}
@media(prefers-reduced-motion:reduce){.wf-site-header *{animation:none!important;transition:none!important}}

/* Elastyc Draft: bind the existing custom and installed components to site typography. */
.wf-site-main{font-family:var(--wf-font-body,Inter,Arial,sans-serif);font-weight:var(--wf-body-weight,400)}
[data-wf-component] :is(h1,h2,h3,h4,h5,h6){font-family:var(--wf-font-heading,Manrope,Arial,sans-serif);font-weight:var(--wf-heading-weight,700)}
.wf-site-main [data-wf-component] :is(button,input[type="submit"],.wf-cta__button,.wf-contact-form__button){font-family:var(--wf-font-body,Inter,Arial,sans-serif);font-weight:var(--wf-button-weight,600)}
.wf-site-main [data-wf-component] :is(input:not([type="submit"]),textarea,select){font-family:var(--wf-font-body,Inter,Arial,sans-serif);font-weight:var(--wf-body-weight,400)}
.wf-site-header :is(.es-nav-link,.es-nav-group-button,.es-nav-toggle,.es-login,.wf-nav-link,.wf-nav-group-label){font-weight:var(--wf-menu-weight,500)}
.wf-site-header :is(.es-contact,.es-nav-mobile-cta),.es-footer-cta{font-weight:var(--wf-button-weight,600)}
.wf-site-header .es-nav-mobile-actions>a.es-nav-mobile-cta{font-weight:var(--wf-button-weight,600)}
.wf-feature-card>a{font-weight:var(--wf-button-weight,600)}
.wf-faq__item summary,.wf-contact-form__form label{font-weight:var(--wf-menu-weight,500)}
.wf-site-main :is(.wf-hero__eyebrow,.wf-cta__eyebrow,.wf-media-text__eyebrow){font-weight:var(--wf-menu-weight,500)}
